type CreatorExportDurationReceipt = Readonly<{
  projectId: string;
  generation: number;
  scenes: Scene[];
  durations: Record<string, { videoUrl: string; durationSec: number }>;
}>;

type CreatorExportDurationCheck = Readonly<{
  projectId: string;
  generation: number;
  scenes: Scene[];
  durations?: CreatorExportDurationReceipt["durations"];
  resolve: (receipt: CreatorExportDurationReceipt | null) => void;
}>;

async function observeCreatorVideoSourceDuration(
  videoUrl: string,
): Promise<{ videoUrl: string; durationSec: number } | null> {
  if (typeof document === "undefined" || !videoUrl.trim()) return null;
  return new Promise((resolve) => {
    const video = document.createElement("video");
    let settled = false;
    const finish = (value: { videoUrl: string; durationSec: number } | null) => {
      if (settled) return;
      settled = true;
      window.clearTimeout(timeoutId);
      video.removeAttribute("src");
      video.load();
      resolve(value);
    };
    const timeoutId = window.setTimeout(() => finish(null), 12_000);
    video.preload = "metadata";
    video.onloadedmetadata = () => {
      if (!matchesExpectedCreatorVideoSource({
        expectedUrl: videoUrl,
        currentSrc: video.currentSrc,
        baseUrl: document.baseURI,
      })) {
        finish(null);
        return;
      }
      const durationSec = Number(video.duration);
      finish(Number.isFinite(durationSec) && durationSec > 0
        ? { videoUrl, durationSec }
        : null);
    };
    video.onerror = () => finish(null);
    video.src = videoUrl;
    video.load();
  });
}

