  const getProjectStatusLabel = (value: unknown) => {
    const project = hasCreatorProjectCardDisplayValue(value) ? value : undefined;
    if (project?.exported_movie_url) {
      return uiLanguage === "en" ? "🎬 Ready" : "🎬 Hazır";
    }

    if (Array.isArray(project?.scenes) && project.scenes.length > 0) {
      return uiLanguage === "en" ? "⏳ In Progress" : "⏳ Devam Ediyor";
    }

    return uiLanguage === "en" ? "🧩 Draft" : "🧩 Taslak";
  };

  const getCreatorProjectSnapshot = (value: unknown) => {
    const project = hasCreatorProjectCardDisplayValue(value) ? value : undefined;
    const projectScenes: unknown[] = Array.isArray(project?.scenes) ? project.scenes : [];
    const totalScenes = projectScenes.length;
    const visualReadyCount = projectScenes.filter((value) => {
      const scene = hasCreatorProjectCardDisplayValue(value) ? value : undefined;
      return Boolean(scene?.image || (scene?.videoUrl && scene?.videoStatus === "done"));
    }).length;
    const voiceReadyCount = projectScenes.filter((value) => {
      const scene = hasCreatorProjectCardDisplayValue(value) ? value : undefined;
      const narrationReady =
        !String(scene?.narration || "").trim() || Boolean(scene?.audioUrl);
      const dialogueReady =
        !String(scene?.dialogue || "").trim() ||
        Boolean(scene?.dialogueAudioUrl);

      return narrationReady && dialogueReady;
    }).length;
    const movieResult = project?.exported_movie_result;
    const lifecycle = parseCreatorProjectLifecycleSnapshot(
      hasCreatorProjectCardDisplayValue(movieResult) ? movieResult.projectLifecycle : undefined,
    );

    if (lifecycle) {
      return {
        totalScenes: lifecycle.totalScenes || totalScenes,
        visualReadyCount: lifecycle.visualReadyCount,
        voiceReadyCount: lifecycle.voiceReadyCount,
        exported: lifecycle.status === "exported",
        status: lifecycle.status,
        progress: lifecycle.progress,
      };
    }

    const exported = Boolean(project?.exported_movie_url);
    const assetsReady =
      totalScenes > 0 &&
      visualReadyCount >= totalScenes &&
      voiceReadyCount >= totalScenes;
    const status: CreatorProjectLifecycleStatus = exported
      ? "final_video_ready"
      : assetsReady
        ? "production_ready"
        : totalScenes > 0
          ? "production_in_progress"
          : "draft";
    const baseProgress = project?.title || project?.input_prompt ? 15 : 0;
    const planProgress = totalScenes > 0 ? 20 : 0;
    const visualProgress =
      totalScenes > 0 ? (visualReadyCount / totalScenes) * 25 : 0;
    const voiceProgress =
      totalScenes > 0 ? (voiceReadyCount / totalScenes) * 25 : 0;
    const exportProgress = exported ? 15 : 0;
    const progress = exported
      ? 78
      : Math.min(
          62,
          Math.round(
            baseProgress +
              planProgress +
              visualProgress +
              voiceProgress +
              exportProgress,
          ),
        );

    return {
      totalScenes,
      visualReadyCount,
      voiceReadyCount,
      exported,
      status,
      progress,
    };
  };

  const formatCreatorProjectUpdatedAt = (value?: string) => {
    if (!value) {
      return uiLanguage === "en" ? "Not saved yet" : "Henüz kaydedilmedi";
    }

    const date = new Date(value);
    if (Number.isNaN(date.getTime())) {
      return uiLanguage === "en" ? "Update time unavailable" : "Güncelleme zamanı bulunamadı";
    }

    return date.toLocaleString(uiLanguage === "en" ? "en-US" : "tr-TR", {
      year: "numeric",
      month: "short",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });
  };

